            disease.decrementStepsBeforeDeath();
            spreadDisease();
            checkForFatalDisease();
            incrementHunger();
        }
    }
    /**
     * Check if the disease is fatal to the animal.
     */
    private void checkForFatalDisease()
    {
        if(hasDisease() && disease.diseaseFinished())
